select status, hour(paid_at) as paid_hour, sum(case when method = 'cash' then 1 else 0 end) as cash_count, round(stddev(amount), 2) as stddev_amount, sum(case when status = 'FAILED' then amount else 0 end) as failed_amount from payments where method in ('promptpay', 'cash') and to_date(paid_at) < '2023-12-16' group by status, hour(paid_at) order by cash_count desc, status, paid_hour limit 3;
